when parsing strings, allow a trailing decimal point (fixes a
 problem introduced in 3081a627cebdc1fc119425c7a9f009dbb6bec8e8)

Here is the root cause:
The bug was caused by the parsing logic in the `VpAlloc` function, which did not account for strings that end with a decimal point. This oversight led to invalid values being raised as errors when a trailing decimal point was present, which was not the intended behavior for valid numeric representations.

Here is the patch:
  */
 VP_EXPORT Real *
 VpAlloc(size_t mx, const char *szVal)
 {
     const char *orig_szVal = szVal;
     size_t i, ni, ipn, ipf, nf, ipe, ne, dot_seen, exp_seen, nalloc;
     char v, *psz;
     int  sign=1;
     Real *vp = NULL;
     size_t mf = VpGetPrecLimit();
     VALUE buf;

     mx = (mx + BASE_FIG - 1) / BASE_FIG;    /* Determine allocation unit. */
     if (mx == 0) ++mx;

     if (szVal) {
         while (ISSPACE(*szVal)) szVal++;
         if (*szVal != '#') {
             if (mf) {
                 mf = (mf + BASE_FIG - 1) / BASE_FIG + 2; /* Needs 1 more for div */
                 if (mx > mf) {
                     mx = mf;
                 }
             }
         }
         else {
             ++szVal;
         }
     }
     else {
         /* necessary to be able to store */
         /* at least mx digits. */
         /* szVal==NULL ==> allocate zero value. */
         vp = VpAllocReal(mx);
         /* xmalloc() alway returns(or throw interruption) */
         vp->MaxPrec = mx;    /* set max precision */
         VpSetZero(vp, 1);    /* initialize vp to zero. */
         return vp;
     }

     /* Skip all '_' after digit: 2006-6-30 */
     ni = 0;
     buf = rb_str_tmp_new(strlen(szVal) + 1);
     psz = RSTRING_PTR(buf);
     i   = 0;
     ipn = 0;
     while ((psz[i] = szVal[ipn]) != 0) {
         if (ISSPACE(psz[i])) {
             psz[i] = 0;
             break;
         }
         if (ISDIGIT(psz[i])) ++ni;
         if (psz[i] == '_') {
             if (ni > 0) {
                 ipn++;
                 continue;
             }
             psz[i] = 0;
             break;
         }
         ++i;
         ++ipn;
     }
     szVal = psz;

     /* Check on Inf & NaN */
     if (StrCmp(szVal, SZ_PINF) == 0 || StrCmp(szVal, SZ_INF) == 0 ) {
         vp = VpAllocReal(1);
         vp->MaxPrec = 1;    /* set max precision */
         VpSetPosInf(vp);
         return vp;
     }
     if (StrCmp(szVal, SZ_NINF) == 0) {
         vp = VpAllocReal(1);
         vp->MaxPrec = 1;    /* set max precision */
         VpSetNegInf(vp);
         return vp;
     }
     if (StrCmp(szVal, SZ_NaN) == 0) {
         vp = VpAllocReal(1);
         vp->MaxPrec = 1;    /* set max precision */
         VpSetNaN(vp);
         return vp;
     }

     /* check on number szVal[] */
     ipn = i = 0;
     if      (szVal[i] == '-') { sign=-1; ++i; }
     else if (szVal[i] == '+')            ++i;
     /* Skip digits */
     ni = 0;            /* digits in mantissa */
     while ((v = szVal[i]) != 0) {
         if (!ISDIGIT(v)) break;
         ++i;
         ++ni;
     }
     nf  = 0;
     ipf = 0;
     ipe = 0;
     ne  = 0;
-    dot_seen = 0;
     exp_seen = 0;
     if (v) {
         /* other than digit nor \0 */
         if (szVal[i] == '.') {    /* xxx. */
-            dot_seen = 1;
             ++i;
             ipf = i;
             while ((v = szVal[i]) != 0) {    /* get fraction part. */
                 if (!ISDIGIT(v)) break;
                 ++i;
                 ++nf;
             }
         }
         ipe = 0;        /* Exponent */

         switch (szVal[i]) {
             case '\0':
                 break;
             case 'e': case 'E':
             case 'd': case 'D':
                 exp_seen = 1;
                 ++i;
                 ipe = i;
                 v = szVal[i];
                 if ((v == '-') || (v == '+')) ++i;
                 while ((v=szVal[i]) != 0) {
                     if (!ISDIGIT(v)) break;
                     ++i;
                     ++ne;
                 }
                 break;
             default:
                 break;
         }
     }
-    if (((ni == 0 || dot_seen) && nf == 0) || (exp_seen && ne == 0)) {
+    if ((ni == 0 && nf == 0) || (exp_seen && ne == 0)) {
 	VALUE str = rb_str_new2(orig_szVal);
 	rb_raise(rb_eArgError, "invalid value for BigDecimal(): \"%"PRIsVALUE"\"", str);
     }

     nalloc = (ni + nf + BASE_FIG - 1) / BASE_FIG + 1;    /* set effective allocation  */
     /* units for szVal[]  */
     if (mx == 0) mx = 1;
     nalloc = Max(nalloc, mx);
     mx = nalloc;
     vp = VpAllocReal(mx);
     /* xmalloc() alway returns(or throw interruption) */
     vp->MaxPrec = mx;        /* set max precision */
     VpSetZero(vp, sign);
     VpCtoV(vp, &szVal[ipn], ni, &szVal[ipf], nf, &szVal[ipe], ne);
     rb_str_resize(buf, 0);
     return vp;
 }



